#    le Colisée s'écrase et les ronds deviennent des ovales.
MAQ_W, MAQ_H = 1517.0, 1005.0
MARGIN_X = 5 * mm
GUTTER_X = 4 * mm
CARD_W = (PAGE_W - 2 * MARGIN_X - (COLS_PAGE - 1) * GUTTER_X) / COLS_PAGE
CARD_H = CARD_W * MAQ_H / MAQ_W
MARGIN_TOP = 8 * mm
MARGIN_BOT = 6 * mm
GUTTER_Y = (PAGE_H - MARGIN_TOP - MARGIN_BOT - ROWS_PAGE * CARD_H) / (ROWS_PAGE - 1)

