def _tracer_decor(c, x0, y0):
    """Pose le dessin de la maquette (x0, y0 = coin bas-gauche du carton).
    ⚠️ UN SEUL remplissage pour tout le dessin : dessiné contour par
    contour, ça ferait mille ordres de tracé par carton et l'imprimante
    s'étranglerait dessus (leçon du 19/09)."""
    def X(v):
        return x0 + v / 1000.0 * CARD_W

    def Y(v):
        return y0 + CARD_H - v / 1000.0 * CARD_H

    p = c.beginPath()
    for contour in _DECOR.split("|"):
        i = 0
        while i < len(contour):
            op = contour[i]
            i += 1
            j = i
            while j < len(contour) and contour[j] not in "mlc":
                j += 1
            v = [float(t) for t in contour[i:j].split(",")]
            i = j
            if op == "m":
                p.moveTo(X(v[0]), Y(v[1]))
            elif op == "l":
                p.lineTo(X(v[0]), Y(v[1]))
            else:
                p.curveTo(X(v[0]), Y(v[1]), X(v[2]), Y(v[3]), X(v[4]), Y(v[5]))
        p.close()
    c.drawPath(p, stroke=0, fill=1, fillMode=FILL_EVEN_ODD)


def _forme_decor(c, couleur_hex):
    """Le dessin n'est gravé qu'UNE FOIS par couleur dans le PDF ; chaque
    carton s'y réfère. Sans ça une rame pèserait des centaines de Mo."""
    nom = "ROMA_" + str(couleur_hex).lstrip("#")
    faites = getattr(c, "_roma_formes", None)
    if faites is None:
        faites = set()
        c._roma_formes = faites
    if nom not in faites:
        c.beginForm(nom, lowerx=0, lowery=0, upperx=CARD_W, uppery=CARD_H)
        col = colors.HexColor(couleur_hex)
        c.setFillColor(col)
        c.setStrokeColor(col)
        _tracer_decor(c, 0, 0)
        c.endForm()
        faites.add(nom)
    return nom


def _gen_carte(rng):
    """6 pairs, un par plage, de gauche à droite."""
    return [rng.choice([n for n in range(a, b + 1) if n % 2 == 0]) for a, b in PLAGES]


def _dessiner_carte(c, x0, y0, nums, couleur_hex, serie, style="eco",
                    nom_enseigne="", telephone="", titre_jeu=""):
    police_ch, gris_ch = _style_chiffres(style)
    col = colors.HexColor(couleur_hex)

    def X(v):
        return x0 + v / 1000.0 * CARD_W

    def Y(v):
        return y0 + CARD_H - v / 1000.0 * CARD_H

    # 1) LE DESSIN DE MAEVA, tel quel
    c.saveState()
    c.translate(x0, y0)
    c.doForm(_forme_decor(c, couleur_hex))
    c.restoreState()

    # 2) LE N° DE SÉRIE, dans la boîte que sa maquette a prévue
    c.setFillColor(col)
    c.setFont(POLICE, 7.5)
    c.drawCentredString(X(SERIE_X), Y(SERIE_Y), "%05d" % serie)

    # 3) LA PERSONNALISATION, à la place de « 2Kea&Associé »
    nom = (str(nom_enseigne).replace("|", " ").strip() or "2Kea&Associ\u00e9")
    if titre_jeu and "ROMA" not in titre_jeu.strip().upper() and not nom_enseigne:
        nom = titre_jeu.strip()
    if telephone:
        nom += "  " + str(telephone).strip()
    libre = PIED_LARG / 1000.0 * CARD_W
    t_nom = 8.0
    while t_nom > 3.6 and pdfmetrics.stringWidth(nom, "Helvetica-Bold", t_nom) > libre:
        t_nom -= 0.2
    c.setFillColor(colors.black)
    c.setFont("Helvetica-Bold", t_nom)
    c.drawCentredString(X(PIED_X), Y(PIED_Y), nom)

    # 4) LES SIX CHIFFRES, dans SES ronds (on n'en dessine aucun)
    for k, val in enumerate(nums):
        cx = X(RONDS_X[k])
        cy = Y(RONDS_Y)
        if _sec and CHIFFRES_MICRO:
            _sec.chiffre_micro(c, val, cx, cy - _T_NUM * 0.36, _T_NUM,
                               gris_ch, police_ch, taille_micro=MICRO_PT)
        else:
            c.setFillColor(gris_ch)
            c.setFont(police_ch, _T_NUM)
            c.drawCentredString(cx, cy - _T_NUM * 0.36, str(val))


def generer_pdf(nb_cartes=8, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="", telephone="",
                style="eco", evenement_id="", page_start=1):
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=A4, pageCompression=1)

    nb_cartes = max(1, min(int(nb_cartes), 10000))
    nb_pages = (nb_cartes + CARTES_PAGE - 1) // CARTES_PAGE

    # ⚠️ GRAINE : deux lots lancés avec le même serie_start sortent
    #    identiques. Pour un second tirage, décaler serie_start.
    rng = random.Random(690000 + int(serie_start))
    serie = int(serie_start)
    faites = 0
    no_page = max(1, int(page_start))

    # ⚠️ on grave le dessin AVANT d'ouvrir la première page
    if couleur:
        _teintes = [couleur_perso.strip()] if couleur_perso.strip() else list(RAINBOW)
    else:
        _teintes = ["#000000"]
    for _t in _teintes:
        _forme_decor(c, _t)

    for _ in range(nb_pages):
        c.setFillColor(GRIS_CLAIR)
        c.setFont(POLICE, 6)
        c.drawCentredString(PAGE_W / 2, PAGE_H - 4.2 * mm, "%d" % no_page)

        for slot in range(CARTES_PAGE):
            if faites >= nb_cartes:
                break
            ci = slot % COLS_PAGE
            ri = slot // COLS_PAGE
            x0 = MARGIN_X + ci * (CARD_W + GUTTER_X)
            y0 = PAGE_H - MARGIN_TOP - (ri + 1) * CARD_H - ri * GUTTER_Y

            if couleur:
                coul = couleur_perso.strip() if couleur_perso.strip() else RAINBOW[faites % len(RAINBOW)]
            else:
                coul = "#000000"

            _dessiner_carte(c, x0, y0, _gen_carte(rng), coul, serie, style=style,
                            nom_enseigne=nom_evenement, telephone=telephone,
                            titre_jeu=titre_jeu)
            serie += 1
            faites += 1

        c.showPage()
        no_page += 1

    c.save()
    buf.seek(0)
    return buf.read()
